# Quêtes secondaires : six commissions (rapporter un objet resté dans la carte voisine) et quatre primes (un adversaire nommé).
import json
COM = [  # carte de l'avis, carte de l'objet, id, nom, icône de base, texte de l'avis, description, récompense, remerciement
 ('egouts', 'egouts2', 'q_gaffe', "Gaffe du maître égoutier", 'cle_bois', "Avis cloué au mur : « Perdu ma gaffe dans le collecteur du bas. Trente ans qu'elle me connaît. Bonne récompense à qui la remonte. Maître Josse. »", "Une longue perche ferrée, polie par trente ans de vase. Maître Josse y tient.", [['or', 40], ['onguent', 0]], "Vous accrochez la gaffe sous l'avis. Derrière la planche, Maître Josse avait préparé la récompense, en homme qui fait confiance."),
 ('mine', 'mine2', 'q_lampe', "Lampe du vieux Hubert", 'lanterne', "Avis du contremaître : « La lampe de sûreté du vieux Hubert est restée en bas. Lui est remonté, pas elle. Sa veuve la réclame. Prime de la compagnie. »", "Une lampe de mineur cabossée, gravée d'un H. Elle a encore de l'huile, par fidélité.", [['or', 45], ['huile', 0]], "Vous déposez la lampe sur le pupitre. La caisse de la compagnie s'ouvre : pour une fois, elle paie."),
 ('abbaye', 'crypte', 'q_missel', "Missel de l'abbé Gontier", 'carnet', "Note du frère bibliothécaire : « Le missel de l'abbé Gontier est resté dans la crypte lors de sa dernière messe, qui fut longue. Qui le rapporte aura nos prières, et mieux. »", "Un missel enluminé. Entre les pages, des recettes. L'abbé Gontier priait surtout avant les repas.", [['or', 50], ['herbes', 0], ['onguent', 0]], "Le missel retrouve son pupitre. Le frère bibliothécaire a laissé, bien en vue, de quoi vous remercier sans vous parler."),
 ('foret', 'ruines', 'q_trompe', "Trompe du grand veneur", 'amulette', "Gravé sur la borne : « J'ai perdu ma trompe aux vieilles pierres, en fuyant plus vite que mon honneur. Qui la rapporte ici sera payé. Le grand veneur. »", "Une trompe de chasse en corne cerclée d'argent. Elle sonne encore, un peu vexée.", [['or', 55], ['potfeu', 0]], "Vous posez la trompe sur la borne. Dessous, une bourse attendait, moisie mais pleine."),
 ('cour', 'palais2', 'q_ecritoire', "Écritoire de la reine", 'sceau', "Billet d'une chambrière : « L'écritoire de Sa Majesté a disparu des appartements depuis que le chancelier trie le courrier. Elle est quelque part au premier. Discrétion et récompense. »", "Une écritoire de voyage, aux armes d'Austrevie. On en a forcé la serrure. Mal.", [['or', 70], ['onguent', 0]], "Vous glissez l'écritoire derrière le pupitre. Le lendemain n'existe pas encore, mais la récompense est déjà là."),
 ('palais2', 'palais3', 'q_dossier', "Dossier Morvane", 'traite_coup', "Mot d'un greffier, non signé : « Le dossier d'instruction du général de Morvane est au cabinet, sous clé de personne. Je paierais cher pour le lire avant qu'il ne brûle. »", "Votre propre dossier d'accusation. Les lettres y sont classées par ordre de fausseté.", [['or', 80], ['onguent', 0], ['potfeu', 0]], "Vous laissez le dossier au greffier inconnu. Il a tenu parole d'avance : la somme est là, avec un mot. « Je le savais. »"),
]
PRI = [  # carte, id du monstre, type de base, nom, texte de l'avis, récompense
 ('village', 'e_rouquin', 'pillard', "le Rouquin", "Avis du bailli : « Mort ou vif, plutôt mort : le Rouquin, pillard, voleur de poules et de la caisse du bailliage. Vingt écus. Trente s'il rend les poules. »", [['or', 35], ['pain', 0]]),
 ('marais', 'e_gueule', 'ragondin', "la Vieille Gueule", "Planche du passeur : « Prime pour la Vieille Gueule, ragondin de la taille d'un veau, qui m'a mangé une rame et la moitié d'un client. »", [['or', 50], ['onguent', 0]]),
 ('faubourgs', 'e_sergot', 'garde', "le sergent Malebouche", "Affiche arrachée à demi : « Le sergent Malebouche, du guet, rançonne les faubourgs pour son compte. Les bourgeois se cotisent pour qui lui apprendra la probité. »", [['or', 60], ['vin', 0]]),
 ('camp', 'e_recruteur', 'reitre', "le Recruteur", "Note d'un déserteur, plantée d'un couteau : « Le Recruteur de Karst nous a tous enrôlés ivres. Ma solde entière à qui lui fera signer son propre congé. »", [['or', 70], ['potfeu', 0]]),
]
ITEMS = {c[2]: "{n:%s,k:'key',p:0,d:%s}" % (json.dumps(c[3], ensure_ascii=False), json.dumps(c[6], ensure_ascii=False)) for c in COM}
ICONS = [[c[2], c[4]] for c in COM]
JS = "\n/* quêtes secondaires : commissions (objet à rapporter de la carte voisine) et primes (adversaire nommé) */\nconst QCOM=" + json.dumps([dict(a=c[0], b=c[1], it=c[2], txt=c[5], loot=c[7], ok=c[8]) for c in COM], ensure_ascii=False) + ",QPRI=" + json.dumps([dict(lv=c[0], id=c[1], base=c[2], n=c[3], txt=c[4], loot=c[5]) for c in PRI], ensure_ascii=False) + r""";
QCOM.forEach((q,i)=>{const A=LEVELS[q.a],B=LEVELS[q.b];if(!A||!B)return;const pa=freeCells(q.a,1,0),pb=freeCells(q.b,1,0);if(!pa||!pb){q.off=1;return;}
 (A.props=A.props||[]).push({id:'qa'+i,k:'pupitre',x:pa[0][0],y:pa[0][1],sc:'qcom',pz:i});(B.props=B.props||[]).push({id:'qb'+i,k:'chest',x:pb[0][0],y:pb[0][1],loot:[[q.it,0]]});});
QPRI.forEach((q,i)=>{const L=LEVELS[q.lv];if(!L||!MON[q.base])return;const b=MON[q.base];MON[q.id]=Object.assign({},b,{n:q.n,spr:b.spr||q.base,hp:Math.round(b.hp*1.9),m:Math.round(b.m*1.3),lv:b.lv+2,sc:(b.sc||.82)*1.12,coward:0,gold:[12,24],ko:cap(q.n)+" s'effondre. La prime est à vous."});
 const pa=freeCells(q.lv,1,0),pm=freeCells(q.lv,1,0,1);if(!pa||!pm){q.off=1;return;}q.at=pm[0];(L.props=L.props||[]).push({id:'qp'+i,k:'stele',x:pa[0][0],y:pa[0][1],sc:'qpri',pz:i});});
SC.qcom=function(p){const q=QCOM[p.pz],f='q_'+q.it;if(S.flags[f]===2){log("L'affaire est classée. On vous a payé, ce qui est rare.");return;}
 if(has(q.it)){consume(q.it);S.flags[f]=2;sfx('coin');const got=q.loot.map(l=>give(l[0],l[1]||0)),b=best('savoir');if(b)gainXp(b,'savoir',20);log(`<b>${q.ok}</b> Vous recevez : <b>${got.join(', ')}</b>.`);ui();save('auto');return;}
 S.flags[f]=1;sfx('page');say([[null,q.txt]]);};
SC.qpri=function(p){const q=QPRI[p.pz],f='q_'+q.id;if(S.flags[f]===2){log("Prime versée. L'avis ne sert plus qu'à décorer.");return;}
 if(!LS.qsp){LS.qsp=1;if(!LS.mons.some(m=>m.t===q.id)){const m=mkMon(q.id,q.at[0],q.at[1]);LS.mons.push(m);}}S.flags[f]=S.flags[f]||1;sfx('page');say([[null,q.txt]]);};
function questTick(){for(const q of QPRI){if(q.off||q.lv!==S.lv||S.flags['q_'+q.id]===2)continue;const m=LS.mons.find(m=>m.t===q.id);if(m&&m.hp<=0){S.flags['q_'+q.id]=2;sfx('coin');const got=q.loot.map(l=>give(l[0],l[1]||0));log(`<b>Prime : ${q.n} ne nuira plus.</b> Dans sa bourse, de quoi vous payer vous-même : <b>${got.join(', ')}</b>.`);ui();}}}
function questLines(){const l=[];for(const q of QCOM)if(!q.off&&S.flags['q_'+q.it]===1)l.push(`rapporter ${ITEMS[q.it].n.toLowerCase()} (${LEVELS[q.a].name})`);for(const q of QPRI)if(!q.off&&S.flags['q_'+q.id]===1)l.push(`prime sur ${q.n} (${LEVELS[q.lv].name})`);return l;}
"""
